from pathlib import Path
import json
from docx import Document
from docx.shared import Pt, Cm, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

BASE=Path(__file__).resolve().parent.parent/'10 лабораторная'
metrics=json.loads((BASE/'результаты/metrics.json').read_text(encoding='utf-8'))
records=json.loads((BASE/'результаты/traces.json').read_text(encoding='utf-8'))
d=Document()
s=d.sections[0]; s.top_margin=s.bottom_margin=Cm(2); s.left_margin=Cm(2.5); s.right_margin=Cm(2)
normal=d.styles['Normal']; normal.font.name='Times New Roman'; normal.font.size=Pt(12)
normal.paragraph_format.space_after=Pt(6); normal.paragraph_format.line_spacing=1.15
for n in ['Title','Heading 1','Heading 2']:
    d.styles[n].font.name='Times New Roman'; d.styles[n].font.color.rgb=RGBColor(0,0,0)
def p(t): return d.add_paragraph(t)
def h(t): d.add_heading(t,level=1)
def page(): d.add_page_break()
def table(headers,rows):
    t=d.add_table(rows=1, cols=len(headers)); t.style='Table Grid'
    for c,v in zip(t.rows[0].cells,headers): c.text=str(v)
    for row in rows:
        for c,v in zip(t.add_row().cells,row): c.text=str(v)
    for row in t.rows:
        for c in row.cells:
            for par in c.paragraphs:
                par.paragraph_format.space_after=Pt(3)
                for run in par.runs: run.font.size=Pt(10)
    for c in t.rows[0].cells:
        pr=c._tc.get_or_add_tcPr(); sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'E8E8E8'); pr.append(sh)
    return t
def code(t):
    par=p(t); par.paragraph_format.line_spacing=1
    for r in par.runs: r.font.name='Consolas'; r.font.size=Pt(8)

for text in ['Воронежский государственный университет','Технологии искусственного интеллекта']:
    par=p(text); par.alignment=1
p(''); p(''); p('')
par=d.add_paragraph('ОТЧЕТ ПО ЛАБОРАТОРНОЙ РАБОТЕ № 10','Title'); par.alignment=1
par=p('Реализация механизма вывода и объяснения решений'); par.alignment=1
par=p('Вариант 27\nБанковское дело и анализ транзакций'); par.alignment=1
p(''); p('Выполнил: Баженов Н.').alignment=2
p(''); p('Воронеж 2026').alignment=1
page(); h('1 Цель и задачи работы')
p('Цель работы — реализовать объяснимый механизм прямого вывода для банковской антифрод-системы и оценить его качество на транзакциях из ранее созданного хранилища.')
p('Задачи: реализовать сопоставление фактов с правилами, разрешение конфликтов, применение правил и остановку цикла; сформировать трассировку; подключить хранилище; измерить качество на выборке не менее 50 примеров; разобрать ошибки.')
p('Работа выполнена по файлу «Задание 10.pdf», содержащему занятие 12 практикума. Использована база R001–R016 из предыдущей лабораторной. Номер отчета соответствует номеру лабораторной работы.')
h('2 Выбор типа вывода')
table(['Критерий','Особенности задачи','Выбор'],[
['Направление решения','Известны параметры платежа; требуется решение','От фактов к заключению'],
['Заранее известная цель','Категория операции заранее неизвестна','Прямой вывод'],
['Поступление данных','Каждый платеж образует новый набор фактов','Новая рабочая память на платеж']])
p('Прямой вывод удобен для классификации потока платежей: система проверяет все применимые эвристики. Обратный вывод потребовал бы отдельно доказывать каждую предполагаемую категорию.')
h('3 Архитектура и входные данные')
p('Модуль 06_inference_engine.py загружает неизмененную базу rules.json и строки DWH. Метка is_fraud исключается из рабочей памяти и используется только после вывода для оценки. Исходное хранилище открывается только для чтения.')
p('Входы: сумма и ее категория, признак аномальной суммы, тип карты, тип устройства, семейство ОС, неизвестная география, ночная операция и бесплатный почтовый сервис. Отсутствующие поля не заполняются предположениями: правило с неизвестным условием неприменимо.')
page(); h('4 Механизм вывода и конфликты')
p('Цикл выполняет Match → Select → Apply. Правило применяется один раз за счет факта fired_Rxxx. Решение задается первым выбранным правилом; последующие применения накапливают свидетельства и максимальный балл риска. Исходные 16 правил не имеют цепочек предметных промежуточных заключений: трассировка отражает последовательность независимых свидетельств, а не искусственно добавленные зависимости.')
src=(BASE.parent/'anti_fraud_ai_project/06_inference_engine.py').read_text(encoding='utf-8')
code(src[src.index('def match_rules'):src.index('def explain')])
p('Стратегия: больший priority, затем больше атомарных сравнений, затем меньший ID. Так результат не зависит от порядка правил в JSON. Приоритеты блокировки выше приоритетов одобрения. При отсутствии правил возвращается Investigate_SOC, то есть ручная проверка.')
p('Неподвижная точка достигается, когда отсутствуют непримененные подходящие правила. В штатном случае возможно не более 16 применений; лимит 100 шагов защищает от некорректного расширения базы. Максимальный риск является сводным показателем всех свидетельств и может отличаться от риска победившего правила.')
page(); h('5 Интеграция с хранилищем')
p('Реально проверенное подключение — SQLite, файл data/anti_fraud_dwh.db, созданный скриптом 03_load_dwh.py. В нем 100000 транзакций, из них 3311 помечены как мошеннические. Проверка использует первые 1000 строк по transaction_id без подбора по ответу.')
p('В задании указан PostgreSQL. Реализован отдельный режим --postgres: строка подключения читается из POSTGRES_DSN, запрос исполняется через psycopg с преобразованием записей в словари. Подключение к PostgreSQL в данной работе не проверялось: параметры сервера не предоставлены, драйвер psycopg отсутствует. Поэтому результаты ниже относятся только к SQLite; требование фактического запуска в PostgreSQL остается неподтвержденным.')
code(src[src.index('QUERY ='):src.index('def main')])
p('Соединение таблицы фактов с пятью измерениями обеспечивает единый словарь признаков. Поля is_trusted_device, tx_velocity_1h, device_fraud_history и is_risky_email отсутствуют в схеме и не вычисляются. Грубые идентификаторы карты и оборудования недостаточны для достоверного восстановления доверенности и истории атак. Метка текущей транзакции не используется для построения этих признаков.')
h('6 Условия воспроизведения')
p('Из папки проекта: python 06_inference_engine.py --limit 1000. Для PostgreSQL после установки psycopg и задания POSTGRES_DSN: python 06_inference_engine.py --postgres --limit 1000. Сервер должен содержать таблицы ранее разработанной схемы DWH.')
p('Результаты сохраняются в папке «10 лабораторная/результаты»: metrics.json, predictions.csv и traces.json. Запуск не перезаписывает базу правил и таблицы хранилища.')
page(); h('7 Примеры объяснения решений')
p('Функция explain(trace) показывает ID и описание каждого примененного правила, фактические значения, проверяемые условия и добавленные факты. В traces.json также хранится конфликтное множество каждого шага.')
examples=[]
for decision in ['Approve','Challenge_2FA','Decline_Block','Investigate_SOC']:
    r=next((r for r in records if r['decision']==decision),None)
    if r: examples.append(r)
for i,r in enumerate(examples,1):
    d.add_heading(f'Пример {i} Транзакция {r["transaction_id"]}',2)
    p(f'Решение: {r["decision"]}; риск {r["risk_score"]}; фактическая метка {r["actual"]}. Цепочка: '+(' → '.join(t['id'] for t in r['trace']) or 'нет применимых правил')+'.')
    for t in r['trace']:
        p(f'{t["id"]}: {t["description"]}. Факты: '+', '.join(f'{k}={v}' for k,v in t['conditions'].items())+'.')
    if not r['trace']: p('Неизвестные признаки и отсутствие подходящих правил приводят к передаче операции на ручную проверку.')
h('8 Результаты тестирования')
p('Оценка бинарная: is_fraud=1 — мошенничество; предсказание 1 — любое решение, отличное от Approve, включая ручную проверку. Это оценка обнаружения подозрений, а не точности четырех категорий действий: эталонные категории действий отсутствуют.')
table(['Показатель','Результат'],[[ 'Число примеров',metrics['n']],['Верно классифицировано',metrics['correct']],['TP / TN / FP / FN',f'{metrics["TP"]} / {metrics["TN"]} / {metrics["FP"]} / {metrics["FN"]}'],*[[label,f'{metrics[key]*100:.2f}%'] for label,key in [('Accuracy','accuracy'),('Precision','precision'),('Recall','recall'),('F1','f1')]],['Среднее число применений',f'{metrics["mean_steps"]:.3f}'],['Базовая точность всегда легитимно',f'{metrics["majority_accuracy"]*100:.2f}%']])
page(); h('9 Анализ ошибок и ограничения')
errors=[r for r in records if r['actual']!=r['predicted']]
chosen=[next(r for r in errors if r['actual']==1),next(r for r in errors if r['actual']==0 and r['trace']),next(r for r in errors if r['actual']==0 and not r['trace'])]
for r in chosen:
    d.add_heading(f'Транзакция {r["transaction_id"]}',2)
    p(f'Эталон {r["actual"]}; предсказание {r["predicted"]}; решение {r["decision"]}. Правила: '+(', '.join(t['id'] for t in r['trace']) or 'нет')+'.')
    if r['actual']==1:
        p('Пропуск мошенничества: правило одобрения на основании ограниченных признаков не распознает атаку. Улучшение: дополнить профиль историей устройства и временной частотой, затем проверить новые правила на отдельной выборке.')
    elif r['trace']:
        p('Ложное срабатывание: рисковая эвристика совпала с легитимной операцией. Требуется совместный учет поведения клиента и суммы; один признак не гарантирует мошенничество. Изменение приоритетов нужно проверять на отложенной выборке.')
    else:
        p('Ложное срабатывание обусловлено маршрутизацией неизвестного случая на ручную проверку. Это не доказательство мошенничества. Следует отдельно оценивать долю ручных проверок и качество детектора, а также расширить покрытие правил легитимного поведения.')
p('Accuracy=(TP+TN)/N; Precision=TP/(TP+FP); Recall=TP/(TP+FN); F1=2PR/(P+R). При нулевом знаменателе реализация возвращает 0. В выборке лишь 29 мошеннических операций из 1000. Высокая базовая accuracy 97,1% демонстрирует, почему одной точности недостаточно.')
p('Выборка является последовательным фрагментом хранилища и не гарантирует представительность. База правил не подбиралась по этим результатам. Доказательства производительности в 50 мс и промышленной пригодности не получены.')
h('10 Выводы')
p('Реализованы прямой вывод, детерминированное разрешение конфликтов, защита от повторного применения правил и текстовые объяснения. Проверены 1000 записей реального локального DWH. Accuracy 68,2%, Precision 1,67%, Recall 17,24%, F1 3,05% показывают недостаточное качество текущей базы и неполноту входных признаков. Для улучшения нужны исторические признаки, отдельная оценка ручной проверки и тестирование на отложенных данных. Поддержка PostgreSQL реализована, но ее фактическое подключение требует отдельной проверки.')
page(); h('Приложение Ответы на контрольные вопросы')
answers=[('1 Алгоритм прямого вывода','Сопоставить условия с фактами, выбрать правило, добавить заключение, повторить. Неподвижная точка — состояние, в котором новые факты больше не выводятся. В реализации каждое правило применяется один раз.'),('2 Прямой и обратный вывод','Прямой вывод идет от известных фактов к доступным заключениям и подходит для мониторинга. Обратный начинает с гипотезы и проверяет необходимые предпосылки; он удобен для доказательства конкретной цели или диагностического опроса.'),('3 Трассировка','Упорядоченная запись применений правил, исходных условий и новых фактов. Она позволяет объяснить решение, проверить конфликты и локализовать ошибочную эвристику.'),('4 F1 и accuracy','F1=2·Precision·Recall/(Precision+Recall). Метрика учитывает ложные тревоги и пропуски положительного класса и полезна при дисбалансе классов. Accuracy может быть высокой при полном игнорировании редкого мошенничества.'),('5 Причины низкого качества','Неполные или ошибочные факты, слабое покрытие базы, неверные приоритеты, несовпадение распределений и слишком общие правила. Способы исправления: аудит данных, новые исторические признаки, экспертная проверка базы, пересмотр конфликтов и независимая проверка качества.')]
for title,body in answers: d.add_heading(title,2); p(body)
h('Использованные материалы')
p('1. Задание 10.pdf. Практикум по технологиям искусственного интеллекта. Занятие 12. С. 65–69.')
p('2. Материалы проекта: 03_load_dwh.py, data/rules.json, sql/dwh_schema.sql, data/anti_fraud_dwh.db.')
p('3. Отчет предыдущей лабораторной работы по продукционной базе знаний, вариант 27.')
for style in d.styles:
    pr=style.element.find(qn('w:pPr'))
    if pr is not None:
        for border in list(pr.findall(qn('w:pBdr'))): pr.remove(border)
for par in d.paragraphs:
    pr=par._p.get_or_add_pPr()
    border=OxmlElement('w:pBdr')
    for side in ['top','left','bottom','right','between','bar']:
        node=OxmlElement('w:'+side); node.set(qn('w:val'),'nil'); border.append(node)
    pr.append(border)
d.save(BASE/'Отчёт 10 лабораторная - Баженов Н.docx')
